/**
 * Shared engine for the Cursor pull relays (`--cursor-events` for GitHub SCM
 * events, and the automatic Slack relay for `cursorAccount` channels). Both
 * long-poll a per-principal Cursor backend stream with a durable client-owned
 * offset and a heartbeat registration; only the subscribe/poll paths, the
 * registration body/response, and the per-event dispatch differ. Those vary
 * as data or closures on a {@link RelayAdapter}, so this engine is written
 * once and tested through each provider's relay.
 */
import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { LOG_PREFIX } from "./distribution.js";
import { isRecord } from "./is-record.js";
const OFFSET_SNAPSHOT_VERSION = 1;
const DEFAULT_POLL_WAIT_MS = 25_000;
const DEFAULT_POLL_LIMIT = 100;
const DEFAULT_REGISTER_INTERVAL_MS = 5 * 60 * 1000;
const CONSUMER_ID_PATTERN = /^[a-zA-Z0-9_-]{1,64}$/;
const DEFAULT_IDLE_POLL_DELAY_MS = 250;
const MIN_BACKOFF_MS = 1_000;
const MAX_BACKOFF_MS = 30_000;
const AUTH_FAILURE_BACKOFF_MS = 60_000;
/** Attempts per event before the offset advances past it. */
const DISPATCH_ATTEMPTS = 3;
const DISPATCH_RETRY_DELAYS_MS = [250, 1_000];
/** Budget for the best-effort deregistration PUT during stop(). */
const DEREGISTER_TIMEOUT_MS = 1_500;
/** Durable offset snapshot under `<stateDir>/offset.json`. */
export class RelayOffsetStore {
    constructor(stateDir) {
        this.stateDir = stateDir;
    }
    get filePath() {
        return join(this.stateDir, "offset.json");
    }
    async load() {
        try {
            const raw = await readFile(this.filePath, "utf8");
            const parsed = JSON.parse(raw);
            if (isRecord(parsed) &&
                parsed.version === OFFSET_SNAPSHOT_VERSION &&
                typeof parsed.offset === "string") {
                return parsed.offset;
            }
            return undefined;
        }
        catch {
            return undefined;
        }
    }
    async save(offset) {
        await mkdir(this.stateDir, { recursive: true });
        const snapshot = {
            version: OFFSET_SNAPSHOT_VERSION,
            offset,
            updatedAt: new Date().toISOString(),
        };
        // Write-then-rename so a crash mid-write never corrupts the snapshot.
        const tmpPath = `${this.filePath}.tmp`;
        await writeFile(tmpPath, JSON.stringify(snapshot, null, 2), "utf8");
        await rename(tmpPath, this.filePath);
    }
}
/** Compare stream offsets (`<ms>-<seq>`). */
export function compareStreamOffsets(a, b) {
    const [aMs, aSeq] = splitOffset(a);
    const [bMs, bSeq] = splitOffset(b);
    if (aMs !== bMs)
        return aMs < bMs ? -1 : 1;
    if (aSeq !== bSeq)
        return aSeq < bSeq ? -1 : 1;
    return 0;
}
function splitOffset(offset) {
    const dash = offset.indexOf("-");
    const ms = Number(dash === -1 ? offset : offset.slice(0, dash));
    const seq = dash === -1 ? 0 : Number(offset.slice(dash + 1));
    return [Number.isFinite(ms) ? ms : 0, Number.isFinite(seq) ? seq : 0];
}
export function describeRelayError(error) {
    return error instanceof Error ? error.message : String(error);
}
/** Must match server-shared `AGENT_SERVE_GENERATION_HEADER`. */
export const AGENT_SERVE_GENERATION_HEADER = "x-agent-serve-generation";
/** Must match server-shared `AGENT_SERVE_GENERATION_ENV_VAR`. */
export const AGENT_SERVE_GENERATION_ENV_VAR = "AGENT_SERVE_GENERATION";
export function resolveAgentServeDeploymentGeneration(explicit) {
    if (explicit !== undefined && Number.isSafeInteger(explicit) && explicit > 0) {
        return explicit;
    }
    const raw = process.env[AGENT_SERVE_GENERATION_ENV_VAR]?.trim();
    if (raw === undefined || raw.length === 0) {
        return undefined;
    }
    if (!/^\d+$/.test(raw)) {
        return undefined;
    }
    const parsed = Number(raw);
    if (!Number.isSafeInteger(parsed) || parsed <= 0) {
        return undefined;
    }
    return parsed;
}
export class CursorRelayCore {
    constructor(options) {
        this.options = options;
        this.running = false;
        this.consumerId = "";
        /** Whether any registration succeeded (gates the stop-time deregister). */
        this.registeredOnce = false;
        this.offsetStore = new RelayOffsetStore(options.stateDir);
        this.fetchImpl = options.fetchImpl ?? fetch;
        this.deploymentGeneration = resolveAgentServeDeploymentGeneration(options.deploymentGeneration);
    }
    start() {
        if (this.running)
            return;
        this.running = true;
        this.abort = new AbortController();
        this.consumePromise = this.run();
    }
    /**
     * Registration-gated lifecycle: no anchor and no consumption until one
     * registration succeeded — anchoring "now" while unsubscribed would
     * silently miss every delivery in between.
     */
    async run() {
        await this.resolveConsumerId();
        const registered = await this.registerUntilSuccess();
        if (!registered)
            return;
        this.registerTimer = setInterval(() => {
            this.heartbeatPromise = this.registerOnce();
        }, DEFAULT_REGISTER_INTERVAL_MS);
        this.registerTimer.unref?.();
        await this.consumeLoop();
    }
    /**
     * Durable consumer identity for this state root (memoized), so this host's
     * registrations never clobber a sibling consumer's on the same key and
     * survive restarts. Public so callers can bind transports with it before
     * `start()` (the Slack relay proxies outbound calls under this id).
     */
    async resolveConsumerId() {
        if (this.consumerId !== "") {
            return this.consumerId;
        }
        const filePath = join(this.options.stateDir, "consumer-id");
        try {
            const existing = (await readFile(filePath, "utf8")).trim();
            if (CONSUMER_ID_PATTERN.test(existing)) {
                this.consumerId = existing;
                return existing;
            }
        }
        catch {
            // Missing or unreadable: mint below.
        }
        const minted = randomUUID();
        try {
            await mkdir(this.options.stateDir, { recursive: true });
            const tmpPath = `${filePath}.tmp`;
            await writeFile(tmpPath, `${minted}\n`, "utf8");
            await rename(tmpPath, filePath);
        }
        catch (error) {
            this.log(`could not persist consumer id (${describeRelayError(error)}); using an ephemeral one for this run`);
        }
        this.consumerId = minted;
        return minted;
    }
    async stop() {
        if (!this.running)
            return;
        this.running = false;
        if (this.registerTimer !== undefined) {
            clearInterval(this.registerTimer);
            this.registerTimer = undefined;
        }
        this.abort?.abort();
        // Bounded wait: server close must never hang on a poll that ignores the
        // abort (offsets are saved as events are processed, so cutting the loop
        // loose loses nothing).
        await Promise.race([
            this.consumePromise?.catch(() => { }),
            new Promise((resolve) => {
                const timer = setTimeout(resolve, 2_000);
                timer.unref?.();
            }),
        ]);
        // A heartbeat re-registration may be in flight (its fetch was just
        // aborted); let it settle so it cannot land after the deregistration.
        await this.heartbeatPromise?.catch(() => { });
        await this.deregister();
    }
    /**
     * Best-effort empty-scope PUT on clean stop, so this consumer's
     * registration is dropped immediately instead of lingering until its
     * server-side TTL. A ghost registration keeps this host's agent names
     * live and makes name routing ambiguous for a redeployed sibling with a
     * fresh consumer id. Failures only log — the TTL still cleans up.
     */
    async deregister() {
        const adapter = this.options.adapter;
        if (adapter.buildDeregistrationBody === undefined ||
            !this.registeredOnce ||
            this.consumerId === "") {
            return;
        }
        const url = `${this.options.baseUrl.replace(/\/+$/, "")}${adapter.subscribePath}`;
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), DEREGISTER_TIMEOUT_MS);
        timer.unref?.();
        try {
            const response = await this.fetchImpl(url, {
                method: "PUT",
                headers: {
                    authorization: `Bearer ${this.options.apiKey}`,
                    "content-type": "application/json",
                    ...(this.deploymentGeneration === undefined
                        ? {}
                        : {
                            [AGENT_SERVE_GENERATION_HEADER]: String(this.deploymentGeneration),
                        }),
                },
                body: JSON.stringify(adapter.buildDeregistrationBody(this.consumerId)),
                signal: controller.signal,
            });
            if (response.ok) {
                this.log("deregistered on shutdown");
            }
            else {
                this.log(`deregistration failed: ${response.status} (registration lapses by TTL)`);
            }
        }
        catch (error) {
            this.log(`deregistration failed: ${describeRelayError(error)} (registration lapses by TTL)`);
        }
        finally {
            clearTimeout(timer);
        }
    }
    log(line) {
        this.options.logger(`${LOG_PREFIX} ${this.options.adapter.logPrefix}: ${line}`);
    }
    async request(method, path, body) {
        const url = `${this.options.baseUrl.replace(/\/+$/, "")}${path}`;
        return this.fetchImpl(url, {
            method,
            headers: {
                authorization: `Bearer ${this.options.apiKey}`,
                ...(body === undefined ? {} : { "content-type": "application/json" }),
                ...(this.deploymentGeneration === undefined
                    ? {}
                    : {
                        [AGENT_SERVE_GENERATION_HEADER]: String(this.deploymentGeneration),
                    }),
            },
            ...(body === undefined ? {} : { body: JSON.stringify(body) }),
            ...(this.abort === undefined ? {} : { signal: this.abort.signal }),
        });
    }
    /** Retry registration with backoff until it succeeds or the relay stops. */
    async registerUntilSuccess() {
        let backoffMs = MIN_BACKOFF_MS;
        while (this.running) {
            if (await this.registerOnce()) {
                return true;
            }
            await this.sleep(backoffMs);
            backoffMs = Math.min(backoffMs * 2, MAX_BACKOFF_MS);
        }
        return false;
    }
    /**
     * Register (or refresh) via the adapter. Returns true when the server
     * accepted the registration (individual scopes may still have failed
     * validation — the adapter logs those).
     */
    async registerOnce() {
        if (!this.running)
            return false;
        try {
            const response = await this.request("PUT", this.options.adapter.subscribePath, this.options.adapter.buildRegistrationBody(this.consumerId));
            if (!response.ok) {
                const text = await response.text().catch(() => "");
                this.logRegistrationOutcome([
                    `registration failed: ${response.status} ${text.slice(0, 300)}`,
                ]);
                return false;
            }
            const json = (await response.json());
            this.logRegistrationOutcome(this.options.adapter.applyRegistrationResponse(json));
            this.registeredOnce = true;
            return true;
        }
        catch (error) {
            if (this.isAbort(error))
                return false;
            this.logRegistrationOutcome([`registration error: ${describeRelayError(error)}`]);
            return false;
        }
    }
    /** Log registration outcome lines only when they change (heartbeat-quiet). */
    logRegistrationOutcome(lines) {
        const key = lines.join("\n");
        if (key === this.lastRegistrationLog)
            return;
        this.lastRegistrationLog = key;
        for (const line of lines) {
            this.log(line);
        }
    }
    async consumeLoop() {
        let backoffMs = MIN_BACKOFF_MS;
        let offset = await this.offsetStore.load();
        let announcedGap = false;
        while (this.running) {
            try {
                if (offset === undefined) {
                    // First run: anchor at "now" so the agent does not replay (and
                    // react to) the retained backlog of old events.
                    const anchorResponse = await this.request("GET", `${this.options.adapter.pollPath}?after=%24&limit=1`);
                    if (!anchorResponse.ok) {
                        backoffMs = await this.backoffAfterHttpFailure(anchorResponse, backoffMs);
                        continue;
                    }
                    const anchor = await anchorResponse.json();
                    if (!isRecord(anchor) || typeof anchor.nextOffset !== "string") {
                        backoffMs = await this.backoffAfterHttpFailure(anchorResponse, backoffMs);
                        continue;
                    }
                    offset = anchor.nextOffset;
                    await this.offsetStore.save(offset);
                    this.log(`anchored at offset "${offset}"`);
                    backoffMs = MIN_BACKOFF_MS;
                    continue;
                }
                const query = new URLSearchParams({
                    after: offset,
                    limit: String(DEFAULT_POLL_LIMIT),
                    waitMs: String(this.options.pollWaitMs ?? DEFAULT_POLL_WAIT_MS),
                });
                const response = await this.request("GET", `${this.options.adapter.pollPath}?${query.toString()}`);
                if (!response.ok) {
                    backoffMs = await this.backoffAfterHttpFailure(response, backoffMs);
                    continue;
                }
                const pollBody = await response.json();
                if (!isRecord(pollBody) ||
                    typeof pollBody.nextOffset !== "string" ||
                    !Array.isArray(pollBody.events)) {
                    backoffMs = await this.backoffAfterHttpFailure(response, backoffMs);
                    continue;
                }
                const poll = {
                    nextOffset: pollBody.nextOffset,
                    gapDetected: Boolean(pollBody.gapDetected),
                    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the relay adapter names TEvent; the poll client cannot validate every event body
                    events: pollBody.events,
                };
                backoffMs = MIN_BACKOFF_MS;
                if (poll.gapDetected && !announcedGap) {
                    announcedGap = true;
                    this.log("gap detected: events may have been trimmed while this host was offline; resuming from the oldest retained event");
                }
                if (poll.events.length > 0) {
                    announcedGap = false;
                }
                for (const event of poll.events) {
                    if (!this.running)
                        break;
                    // At-least-once dedupe: never re-dispatch at or before the last
                    // processed offset (reads are exclusive-after, so this only fires
                    // on replay after a crash between dispatch and save).
                    if (compareStreamOffsets(event.offset, offset) <= 0)
                        continue;
                    if (this.options.adapter.shouldDispatch(event)) {
                        await this.dispatchWithRetry(event);
                    }
                    offset = event.offset;
                }
                if (poll.nextOffset !== "" && compareStreamOffsets(poll.nextOffset, offset) > 0) {
                    offset = poll.nextOffset;
                }
                if (poll.events.length > 0) {
                    await this.offsetStore.save(offset);
                }
                else {
                    await this.sleep(DEFAULT_IDLE_POLL_DELAY_MS);
                }
            }
            catch (error) {
                if (this.isAbort(error))
                    return;
                this.log(`poll error: ${describeRelayError(error)}`);
                await this.sleep(backoffMs);
                backoffMs = Math.min(backoffMs * 2, MAX_BACKOFF_MS);
            }
        }
    }
    /**
     * Dispatch one event with a small bounded retry before the offset advances
     * past it. Transient local failures (e.g. a connection reset while POSTing
     * to the channel) used to drop the event outright; a poison event still
     * only costs {@link DISPATCH_ATTEMPTS} tries and is then skipped, keeping
     * at-least-once semantics without a retry loop.
     */
    async dispatchWithRetry(event) {
        for (let attempt = 1; attempt <= DISPATCH_ATTEMPTS; attempt++) {
            if (attempt > 1 && !this.running) {
                this.log(`dispatch abandoned at offset ${event.offset}: relay stopping`);
                return;
            }
            try {
                await this.options.adapter.dispatch(event);
                return;
            }
            catch (error) {
                if (attempt === DISPATCH_ATTEMPTS) {
                    this.log(`dispatch failed at offset ${event.offset} after ${attempt} attempts: ${describeRelayError(error)}`);
                    return;
                }
                this.log(`dispatch attempt ${attempt} failed at offset ${event.offset}: ${describeRelayError(error)}; retrying`);
                await this.sleep(DISPATCH_RETRY_DELAYS_MS[Math.min(attempt - 1, DISPATCH_RETRY_DELAYS_MS.length - 1)]);
            }
        }
    }
    /** Log the failure, sleep, and return the backoff for the NEXT failure. */
    async backoffAfterHttpFailure(response, backoffMs) {
        // 409 = generation fence (stale resident after redeploy). Same long
        // backoff as auth: retrying every second cannot heal a wrong generation.
        const isAuthOrFenceFailure = response.status === 401 || response.status === 403 || response.status === 409;
        const sleepMs = isAuthOrFenceFailure ? AUTH_FAILURE_BACKOFF_MS : backoffMs;
        const text = await response.text().catch(() => "");
        this.log(`poll failed: ${response.status} ${text.slice(0, 300)} (retrying in ${Math.round(sleepMs / 1000)}s)`);
        await this.sleep(sleepMs);
        return isAuthOrFenceFailure ? AUTH_FAILURE_BACKOFF_MS : Math.min(backoffMs * 2, MAX_BACKOFF_MS);
    }
    sleep(ms) {
        return new Promise((resolve) => {
            const signal = this.abort?.signal;
            if (signal?.aborted === true) {
                resolve();
                return;
            }
            const finish = () => {
                clearTimeout(timer);
                signal?.removeEventListener("abort", finish);
                resolve();
            };
            const timer = setTimeout(finish, ms);
            timer.unref?.();
            signal?.addEventListener("abort", finish, { once: true });
        });
    }
    isAbort(error) {
        return !this.running || (error instanceof Error && error.name === "AbortError");
    }
}
